MAP
    NAME "SS_MAP_PTAR_MUNICIPAL"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_ptar_municipal.log"
    DEBUG 0
    SYMBOL
        NAME "RomboVerde"
        TYPE pixmap
        IMAGE "includes/symbols/RomboPtarMunicipal.png"
    END #SYMBOL
    LAYER
        NAME "SS_MAP_PTAR_MUNICIPAL"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_planta_tratamiento from (select gm_planta_tratamiento, id_planta_tratamiento, nb_planta_tratamiento, cl_administracion_planta from l_plantas_tratamiento where cl_administracion_planta=2)as c using unique id_planta_tratamiento using srid=32614"
        TYPE POINT
        LABELITEM "nb_planta_tratamiento"
        LABELCACHE on
        CLASS
            NAME "PTAR's Municipales"
            STYLE
                SYMBOL "RomboVerde"
                SIZE 18
                COLOR 8 59 130
                OUTLINECOLOR 8 59 130
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                ALIGN RIGHT
                OFFSET 0 25
                SIZE 15
                #COLOR 8 59 130
                COLOR 0 255 170
                OUTLINECOLOR 0 0 0
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP